#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricApparentPower::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricApparentPower::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricApparentPowerUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricApparentPower::from_base(0.0).auto_unit().unit,
        ElectricApparentPowerUnit::Voltampere
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "VA".parse::<ElectricApparentPowerUnit>(),
        Ok(ElectricApparentPowerUnit::Voltampere)
    );
    assert_eq!(
        format!("2.5 {}", "VA").parse::<ElectricApparentPower>(),
        Ok(ElectricApparentPower::new(
            2.5,
            ElectricApparentPowerUnit::Voltampere
        ))
    );
    assert_eq!(
        "µVA".parse::<ElectricApparentPowerUnit>(),
        Ok(ElectricApparentPowerUnit::Microvoltampere)
    );
    assert_eq!(
        format!("2.5 {}", "µVA").parse::<ElectricApparentPower>(),
        Ok(ElectricApparentPower::new(
            2.5,
            ElectricApparentPowerUnit::Microvoltampere
        ))
    );
    assert_eq!(
        "mVA".parse::<ElectricApparentPowerUnit>(),
        Ok(ElectricApparentPowerUnit::Millivoltampere)
    );
    assert_eq!(
        format!("2.5 {}", "mVA").parse::<ElectricApparentPower>(),
        Ok(ElectricApparentPower::new(
            2.5,
            ElectricApparentPowerUnit::Millivoltampere
        ))
    );
    assert_eq!(
        "kVA".parse::<ElectricApparentPowerUnit>(),
        Ok(ElectricApparentPowerUnit::Kilovoltampere)
    );
    assert_eq!(
        format!("2.5 {}", "kVA").parse::<ElectricApparentPower>(),
        Ok(ElectricApparentPower::new(
            2.5,
            ElectricApparentPowerUnit::Kilovoltampere
        ))
    );
    assert_eq!(
        "MVA".parse::<ElectricApparentPowerUnit>(),
        Ok(ElectricApparentPowerUnit::Megavoltampere)
    );
    assert_eq!(
        format!("2.5 {}", "MVA").parse::<ElectricApparentPower>(),
        Ok(ElectricApparentPower::new(
            2.5,
            ElectricApparentPowerUnit::Megavoltampere
        ))
    );
    assert_eq!(
        "GVA".parse::<ElectricApparentPowerUnit>(),
        Ok(ElectricApparentPowerUnit::Gigavoltampere)
    );
    assert_eq!(
        format!("2.5 {}", "GVA").parse::<ElectricApparentPower>(),
        Ok(ElectricApparentPower::new(
            2.5,
            ElectricApparentPowerUnit::Gigavoltampere
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricApparentPower>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ElectricApparentPower::from_base(6.0);
    let b = ElectricApparentPower::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ElectricApparentPower::<i64>::from_base(7);
    let b = ElectricApparentPower::<i64>::from_base(2);
    assert_eq!(a + b, ElectricApparentPower::from_base(9));
    assert_eq!(a % b, ElectricApparentPower::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ElectricApparentPower<i64>>(),
        ElectricApparentPower::from_base(9)
    );
}
